/* Stylesheet: embedded */
#form .bdsug { top: 39px; }
.bdsug { display: none; position: absolute; width: 535px; background: rgb(255, 255, 255); box-shadow: rgb(237, 237, 237) 1px 1px 3px; border: 1px solid rgb(204, 204, 204) !important; }
.bdsug li { width: 519px; color: rgb(0, 0, 0); font: 14px / 25px arial; padding: 0px 8px; position: relative; cursor: default; }
.bdsug li.bdsug-s { background: rgb(240, 240, 240); }
.bdsug-store span, .bdsug-store b { color: rgb(122, 119, 200); }
.bdsug-store-del { font-size: 12px; color: rgb(102, 102, 102); text-decoration: underline; position: absolute; right: 8px; top: 0px; cursor: pointer; display: none; }
.bdsug-s .bdsug-store-del { display: inline-block; }
.bdsug-ala { display: inline-block; border-bottom: 1px solid rgb(230, 230, 230); }
.bdsug-ala h3 { line-height: 14px; background: url("//www.baidu.com/img/sug_bd.png?v=09816787.png") left center no-repeat; margin: 6px 0px 4px; font-size: 12px; font-weight: 400; color: rgb(123, 123, 123); padding-left: 20px; }
.bdsug-ala p { font-size: 14px; font-weight: 700; padding-left: 20px; }
#m .bdsug .bdsug-direct p { color: rgb(0, 0, 204); font-weight: 700; line-height: 34px; padding: 0px 8px; margin-top: 0px; cursor: pointer; white-space: nowrap; overflow: hidden; }
#m .bdsug .bdsug-direct p img { width: 16px; height: 16px; margin: 7px 6px 9px 0px; vertical-align: middle; }
#m .bdsug .bdsug-direct p span { margin-left: 8px; }
#form .bdsug .bdsug-direct { width: auto; padding: 0px; border-bottom: 1px solid rgb(241, 241, 241); }
#form .bdsug .bdsug-direct p i { font-size: 12px; line-height: 100%; font-style: normal; font-weight: 400; color: rgb(255, 255, 255); background-color: rgb(43, 153, 255); display: inline; text-align: center; padding: 1px 5px; margin-left: 8px; overflow: hidden; }
.bdsug .bdsug-pcDirect { color: rgb(0, 0, 0); font-size: 14px; line-height: 30px; height: 30px; background-color: rgb(248, 248, 248); }
.bdsug .bdsug-pc-direct-tip { position: absolute; right: 15px; top: 8px; width: 55px; height: 15px; display: block; background: url("https://pss.bdstatic.com/r/www/cache/static/protocol/https/global/img/pc_direct_42d6311.png") 0px 0px no-repeat; }
.bdsug li.bdsug-pcDirect-s { background-color: rgb(240, 240, 240); }
.bdsug .bdsug-pcDirect-is { color: rgb(0, 0, 0); font-size: 14px; line-height: 22px; background-color: rgb(245, 245, 245); }
.bdsug .bdsug-pc-direct-tip-is { position: absolute; right: 15px; top: 3px; width: 55px; height: 15px; display: block; background: url("https://pss.bdstatic.com/r/www/cache/static/protocol/https/global/img/pc_direct_42d6311.png") 0px 0px no-repeat; }
.bdsug li.bdsug-pcDirect-is-s { background-color: rgb(240, 240, 240); }
.bdsug .bdsug-pcDirect-s .bdsug-pc-direct-tip, .bdsug .bdsug-pcDirect-is-s .bdsug-pc-direct-tip-is { background-position: 0px -15px; }
.bdsug .bdsug-newicon { color: rgb(146, 146, 146); opacity: 0.7; font-size: 12px; display: inline-block; line-height: 22px; letter-spacing: 2px; }
.bdsug .bdsug-s .bdsug-newicon { opacity: 1; }
.bdsug .bdsug-newicon i { letter-spacing: 0px; font-style: normal; }
.bdsug .bdsug-feedback-wrap { display: none; }
.toggle-underline { text-decoration: none; }
.toggle-underline:hover { text-decoration: underline; }
.bdpfmenu, .usermenu { border: 1px solid rgb(209, 209, 209); position: absolute; width: 105px; top: 36px; z-index: 302; box-shadow: rgb(209, 209, 209) 1px 1px 5px; }
.bdpfmenu { font-size: 12px; background-color: rgb(255, 255, 255); }
.bdpfmenu a, .usermenu a { display: block; text-align: left; padding: 0px 9px; line-height: 26px; text-decoration: none; margin: 0px !important; }
